"""Serializes extracted lock graphs into mod/G1LockPickHelper/Scripts/lockgraphs.lua."""


def lua_string(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def to_lua(locks, build, cache_sha1):
    lines = [
        "-- Generated by tools/extract_lockgraphs.py. Do not edit by hand.",
        "-- edges: AddConnection(src, dst, dir) calls in authored order; the game drops the first round(LockpickPrecision).",
        "return {",
        f"  build = {lua_string(build)},",
        f"  cache_sha1 = {lua_string(cache_sha1)},",
        "  locks = {",
    ]
    for name in sorted(locks):
        lock = locks[name]
        edges = ", ".join(f"{{{src}, {dst}, {d}}}" for src, dst, d in lock["edges"])
        lines.append(f"    [{lua_string(name)}] = {{ plates = {lock['plates']}, edges = {{ {edges} }} }},")
    lines += ["  },", "}", ""]
    return "\n".join(lines)
